import{z as l,x as A,o as E,c as C,q as i,j as B,D as e,d as r,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"上半连续对应","description":"","frontmatter":{"title":"上半连续对应","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/uhc-correspondence.md","filePath":"econ/uhc-correspondence.md","lastUpdated":1791413859000}'),p={name:"econ/uhc-correspondence.md"};function d(h,a,c,m,u,H){const n=A("Mermaid");return E(),C("div",null,[a[2]||(a[2]=i('<h1 id="上半连续对应" tabindex="-1">上半连续对应 <a class="header-anchor" href="#上半连续对应" aria-label="Permalink to &quot;上半连续对应&quot;">​</a></h1><div class="epigraph"><p>对应可以突然变小，不能突然变大：极限点的像必须兜住像的极限。</p><footer>—— 据 Berge, Topological Spaces, 1963；Mas-Colell, Whinston and Green 数学附录；Stokey, Lucas and Prescott 第 3 章整理</footer></div><p>上一课<a href="/econ/kakutani-fixed-point">Kakutani 不动点</a>把上半连续当成假设。需求对应、最佳反应、预算对应是否满足它，还没有词汇。缺口是给对应一套与开集语言配套的连续性，并引出 Berge 极大值定理：最优值连续、最优对应 UHC。后课贝尔曼算子保连续，靠的就是这块，而不是再写一遍 Kakutani。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\Phi:X\\rightrightarrows Y\\)，\\(Y\\) 紧。\\(\\Phi\\) <strong>上半连续</strong>（UHC）：对每个 \\(x\\)，任意含 \\(\\Phi(x)\\) 的开集 \\(V\\)，附近的 \\(x&#39;\\) 有 \\(\\Phi(x&#39;)\\subset V\\)。直观：像不会突然冒出远处的新点。等价（紧值）：图 \\(G=\\{(x,y):y\\in\\Phi(x)\\}\\) 闭——\\(x_n\\to x\\)、\\(y_n\\in\\Phi(x_n)\\)、\\(y_n\\to y\\) \\(\\Rightarrow\\) \\(y\\in\\Phi(x)\\)。</p><p><span class="marginnote">术语翻译：「对应」就是把每个输入映到一个集合而非一个数的函数——比如每个价格对应「所有最优的购物篮」这一整段，而不是一个点。函数是对应的特例：集合里永远只有一个元素。</span></p><p><strong>下半连续</strong>（LHC）：像不会突然瘦掉。开集只要碰到 \\(\\Phi(x)\\)，附近的 \\(\\Phi(x&#39;)\\) 也碰到它。连续对应 = UHC + LHC。预算对应在 \\(p\\gg 0\\) 时连续；最优对应通常只有 UHC，没有 LHC——价格微动，整段需求可以突然收成一个端点。Kakutani 只要 UHC，不要 LHC。这是「需求可以跳瘦、不能跳肥」的精确说法。</p><p><span class="marginnote">直觉类比：UHC 说「像可以越缩越小，但不能突然多出一块」；LHC 说「原本选得到的点不能突然消失」。最优选择常常违反第二条（线段缩成点），却几乎总满足第一条——所以存在性靠 UHC 就够。</span></p><h3 id="uhc-不是逐点连续函数" tabindex="-1">UHC 不是逐点连续函数 <a class="header-anchor" href="#uhc-不是逐点连续函数" aria-label="Permalink to &quot;UHC 不是逐点连续函数&quot;">​</a></h3><p>单值对应 \\(\\{f(x)\\}\\) UHC 当且仅当 \\(f\\) 连续。多值时不要谈 \\(\\|\\Phi(x)-\\Phi(x&#39;)\\|\\)。Hausdorff 距离给出更强的连续，UHC 只是其中一半。把 UHC 读成「\\(\\Phi(x)\\) 随 \\(x\\) 连续变化」会误以为需求函数总存在。完全替代在价格比等于 MRS 时需求是线段，旁边立刻变成顶点：Hausdorff 意义下跳跃，但仍 UHC，因为线段突然变小是允许的。</p><p><span class="marginnote">下半连续保证「附近仍选得到原来那种点」，存在性不靠它；要最优值对参数连续且最优对应 UHC，Berge 需要约束对应连续（两半都要）加目标连续。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Berge 极大值定理：\\(f\\) 连续，\\(\\Gamma\\) 紧值连续，则 \\(V(x)=\\max_{y\\in\\Gamma(x)}f(x,y)\\) 连续，\\(\\Phi(x)=\\arg\\max f\\) 非空紧且 UHC。再加 \\(f\\) 拟凹、\\(\\Gamma\\) 凸，则 \\(\\Phi\\) 凸值——Kakutani 的输入齐了。消费者：\\(\\Gamma\\) 是预算，连续偏好给出连续效用表示之后 \\(f=u\\)，于是马歇尔需求 UHC。本课不重写<a href="/econ/utility-representation">效用函数何时存在</a>，只标明极大值定理吃的是连续实函数。</p><p>闭图检验往往比开集定义好用：取价格序列与需求序列，极限点仍可行、仍最优（偏好连续 \\(\\Rightarrow\\) 极限不被严格更好的点压过）。局部非饱和再把极限预算花光。这些检查在后课需求连续性里重复出现，工具是本课的闭图。</p>',14)),(E(),B(s,null,{default:e(()=>[o(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%9B%BE%E9%97%AD%E3%80%81%E7%B4%A7%E5%80%BC%22%5D%20--%3E%20UHC%5B%22%E4%B8%8A%E5%8D%8A%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20LHC%5B%22%E4%B8%8B%E5%8D%8A%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%20CONT%5B%22%E8%BF%9E%E7%BB%AD%E5%AF%B9%E5%BA%94%22%5D%0A%20%20UHC%20--%3E%20CONT%0A%20%20BERGE%5B%22Berge%EF%BC%9A%E7%BA%A6%E6%9D%9F%E8%BF%9E%E7%BB%AD%E3%80%81%E7%9B%AE%E6%A0%87%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%20V%5B%22%E5%80%BC%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20BERGE%20--%3E%20ARG%5B%22argmax%20%E4%B8%BA%20UHC%22%5D%0A%20%20ARG%20--%3E%20KAK%5B%22%E6%8E%A5%E4%B8%8A%E4%B8%80%E8%AF%BE%20Kakutani%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"UHC 阻止「极限选择来自远处突然冒出的点」：否则闭图被破坏，Kakutani 的近似不动点序列可以对不上极限对应。经济学里这对应：价格序列上的最优束，极限必须是极限价格上的最优束。若偏好不连续，极限束可以掉出上优集，需求失去闭图，存在性证明中的极限出清失败。",-1)),(E(),B(s,null,{default:e(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8F%82%E6%95%B0%20x%20%E5%BE%AE%E5%8A%A8%22%5D%20--%3E%20Q1%7B%22%E5%83%8F%E4%BC%9A%E7%AA%81%E7%84%B6%E5%8F%98%E5%A4%A7%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E4%BC%9A%3A%20%E5%86%92%E5%87%BA%E8%BF%9C%E5%A4%84%E6%96%B0%E7%82%B9%22%7C%20BAD%5B%22%E8%BF%9D%E5%8F%8D%20UHC%3A%20%E6%9E%81%E9%99%90%E9%80%89%E6%8B%A9%E6%9D%A5%E8%B7%AF%E4%B8%8D%E6%98%8E%22%5D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E4%BC%9A%22%7C%20OK1%5B%22UHC%20%E6%88%90%E7%AB%8B%3A%20%E9%97%AD%E5%9B%BE%E5%9C%A8%22%5D%0A%20%20X%20--%3E%20Q2%7B%22%E5%83%8F%E4%BC%9A%E7%AA%81%E7%84%B6%E7%98%A6%E6%8E%89%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E4%BC%9A%3A%20%E7%BA%BF%E6%AE%B5%E6%94%B6%E6%88%90%E4%B8%80%E4%B8%AA%E7%82%B9%22%7C%20SHRINK%5B%22LHC%20%E5%A4%B1%E8%B4%A5%3A%20%E9%9C%80%E6%B1%82%E8%B7%B3%2C%20%E4%BD%86%E4%BB%8D%20UHC%22%5D%0A%20%20Q2%20--%3E%7C%22%E4%B8%8D%E4%BC%9A%22%7C%20OK2%5B%22LHC%20%E6%88%90%E7%AB%8B%3A%20%E5%AF%B9%E5%BA%94%E8%BF%9E%E7%BB%AD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：初学者容易把 UHC 读成「需求随价格连续变化」。实际上 LHC 失败时需求照样跳：完全替代品在临界价格比上，需求从整条线段跳成一个顶点——值函数没跳，选择跳了。</span></p><p>LHC 失败的典型画面：最优集从线段变成点。值函数仍然连续——两端与中点同效用——但选择不连续。比较静态在这些点没有 \\(Dx\\)，只能说对应 UHC。上一单元隐函数在这里停用，是同一现象的两边。</p><p><span class="marginnote">可行对应若只有 UHC 没有 LHC，极大值定理的值函数可能向下跳。预算在 \\(p\\to\\) 边界、某些商品价格趋零时要单独紧化，避免 \\(\\Gamma\\) 爆炸。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把集值分析写成 Kuratowski 讲义，不引入测度弱* 对应（那是宏观分布经济）。也不证明 Kakutani——假设已经在上一课。下一课用 UHC/Berge 保证贝尔曼算子把连续函数送到连续函数，从而压缩有地方作用。</p><p>后课默认：最优对应 UHC；预算在 \\(p\\gg 0\\) 的紧化下连续；说「需求连续」若未经严格凸，只意味 UHC 而非单值连续。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UHC：像不突然变大；紧值时即闭图。</li><li>LHC：像不突然变小；最优对应常常没有它。</li><li>Berge：值连续、argmax UHC；再加凸得凸值。</li><li>Kakutani 消费 UHC 与凸值；比较静态的导数消费单值光滑。</li><li>下一课：<a href="/econ/bellman-equation">贝尔曼方程</a>。</li><li>出处：Berge, <em>Topological Spaces</em>；MWG 数学附录；Stokey–Lucas–Prescott 第 3 章。</li></ul>',8))])}const f=l(p,[["render",d]]);export{x as __pageData,f as default};
